package com.procurement.goodsreceipt.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="goods_receipt_history")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class GoodsReceiptHistory{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="grn_history_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grn_id",nullable=false)private GoodsReceiptNote goodsReceiptNote;@Column(nullable=false)private String action;@Column(name="performed_by")private String performedBy;@Enumerated(EnumType.STRING)@Column(name="old_status")private GrnStatus oldStatus;@Enumerated(EnumType.STRING)@Column(name="new_status")private GrnStatus newStatus;@Column(length=500)private String remarks;@Column(name="performed_at",nullable=false)private LocalDateTime performedAt;@PrePersist void pre(){if(performedAt==null)performedAt=LocalDateTime.now();}}
